def rotate_half(x):
    first = x[..., :x.shape[-1] // 2]
    second = x[..., x.shape[-1] // 2:]
    return torch.cat((-second, first), dim=-1)


def _apply_gqa_rope(query, key, position_embeddings, rotary_interleaved, head_dim):
    if position_embeddings is None:
        return (query, key)
    cos, sin = position_embeddings
    if rotary_interleaved:
        return apply_rotary_pos_emb_interleave(query, key, cos, sin, unsqueeze_dim=2)
    if cos.shape[-1] >= head_dim:
        return apply_rotary_pos_emb(query, key, cos, sin, unsqueeze_dim=2)
    rotary_dim = cos.shape[-1]
    query_rot, query_pass = (query[..., :rotary_dim], query[..., rotary_dim:])
    key_rot, key_pass = (key[..., :rotary_dim], key[..., rotary_dim:])
    cos = cos.unsqueeze(2)
    sin = sin.unsqueeze(2)
    query = torch.cat((query_rot * cos + rotate_half(query_rot) * sin, query_pass), dim=-1)
    key = torch.cat((key_rot * cos + rotate_half(key_rot) * sin, key_pass), dim=-1)
    return (query, key)


def _projections_can_fuse(projections):
    biases = tuple((projection.bias for projection in projections))
    return len({projection.in_features for projection in projections}) == 1 and len({projection.weight.requires_grad for projection in projections}) == 1 and (all((bias is None for bias in biases)) or all((bias is not None for bias in biases))) and (biases[0] is None or len({bias.requires_grad for bias in biases}) == 1)


_COMPRESSED_CAUSAL_MASKS = {}

_COMPRESSED_CAUSAL_MASK_SIZE = 2048

def _get_compressed_causal_mask(device: torch.device) -> torch.Tensor:
    """Return the cached mask required by NPU left-up causal sparse mode."""
    mask = _COMPRESSED_CAUSAL_MASKS.get(device)
    if mask is None:
        mask = torch.triu(torch.ones((_COMPRESSED_CAUSAL_MASK_SIZE, _COMPRESSED_CAUSAL_MASK_SIZE), dtype=torch.bool, device=device), diagonal=1)
        _COMPRESSED_CAUSAL_MASKS[device] = mask
    return mask

