        self.v_head_dim = getattr(module, 'v_head_dim', None) or getattr(config, 'v_head_dim', None) or self.qk_head_dim
        self.qkv_split_sizes = (self.num_key_value_groups * self.qk_head_dim, self.qk_head_dim, self.v_head_dim)
        self.qkv_group_width = sum(self.qkv_split_sizes)

