    def make_transforms(self):
        """Describe reversible source-checkpoint to high-performance conversion."""
        if self._source_is_fused:
            qkv_sources = 'qkv_proj.weight'
            bias_sources: str | list[str] = 'qkv_proj.bias'
        else:
            qkv_sources = [f'{name}.weight' for name in self._source_projection_names]
            bias_sources = [f'{name}.bias' for name in self._source_projection_names]
        transforms: list[WeightConverter] = [WeightConverter(source_patterns=qkv_sources, target_patterns='linear_qkv.weight', operations=[InterleaveQKV(self.num_key_value_heads, self.num_key_value_groups, self.qk_head_dim, self.v_head_dim, self._source_is_fused)])]
        if self.linear_qkv.bias is not None:
            transforms.append(WeightConverter(source_patterns=bias_sources, target_patterns='linear_qkv.bias', operations=[InterleaveQKV(self.num_key_value_heads, self.num_key_value_groups, self.qk_head_dim, self.v_head_dim, self._source_is_fused)]))
        return transforms

    def forward(self, hidden_states, position_embeddings=None, attention_mask=None, past_key_values=None, actual_seq_len=None, **kwargs):
        """Run GQA with the same external contract as Transformers attention."""
        input_shape = hidden_states.shape[:-1]
        qkv_states = self.linear_qkv(hidden_states).view(*input_shape, self.num_key_value_heads, self.qkv_group_width)
        query_states, key_states, value_states = torch.split(qkv_states, self.qkv_split_sizes, dim=-1)
        query_states = query_states.reshape(*input_shape, self.num_heads, self.qk_head_dim)
        if self.q_norm is not None:
            query_states = self.q_norm(query_states)
        if self.k_norm is not None:
            key_states = self.k_norm(key_states)
        query_states, key_states = _apply_gqa_rope(query_states, key_states, position_embeddings, self.rotary_interleaved, self.qk_head_dim)
        query_states = query_states.transpose(1, 2)
        key_states = key_states.transpose(1, 2)
        value_states = value_states.transpose(1, 2)
        if past_key_values is not None:
            key_states, value_states = past_key_values.update(key_states, value_states, self.layer_idx)
        attn_output, attn_weights = self.attention_interface(self, query_states, key_states, value_states, attention_mask, dropout=self.attention_dropout if self.training else 0.0, scaling=self.scaling, sliding_window=self.sliding_window, actual_seq_len=actual_seq_len, **kwargs)
        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        attn_output = self.o_proj(attn_output)
        return (attn_output, attn_weights)

